function minElement(nums) {
  let best = Infinity;
  for (const value of nums) {
    let rest = value;
    let sum = 0;
    while (rest > 0) {
      sum += rest % 10;
      rest = Math.floor(rest / 10);
    }
    best = Math.min(best, sum);
  }
  return best;
}

