function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  const shape = rand();
  const make = () => {
    if (shape < 0.3) {
      // Four digits, each from 5 to 9, keep every digit sum high.
      let value = 0;
      for (let d = 0; d < 4; d++) value = value * 10 + 5 + Math.floor(rand() * 5);
      return value;
    }
    if (shape < 0.5) return [1, 9, 10, 19, 99, 100, 199, 999, 1000, 1999, 9999, 10000][Math.floor(rand() * 12)];
    if (shape < 0.7) return 1 + Math.floor(rand() * 100);
    return 1 + Math.floor(rand() * 10000);
  };
  return [Array.from({ length: n }, make)];
}
